import json,hashlib,pathlib,sys
root=pathlib.Path(__file__).parent
n=int(sys.argv[1]); p=root/f'pair-{n:02d}'
config=json.loads((p/'judge_decisions.json').read_text())
def sha(f): return hashlib.sha256(f.read_bytes()).hexdigest()
ledger=json.loads((p/'claim_ledger.json').read_text()); facts={f['fact_id']:f for f in json.loads((p/'rich_profile.json').read_text())['facts']}
claims=[]
for i,c in enumerate(ledger,1):
    ids=c['fact_ids']; reason='Faithful supplied fact selection/rephrasing; no added material claim.'
    if '**' in c['text']:reason='Dates match the referenced rich-profile date fields; degree completion supports graduation label where present.'
    if len(ids)>1:reason='Combines supplied facts without upgrading ownership, scope, causality or metric.'
    claims.append({'claim_id':f'P{n:02d}-{c["language"]}-C{i:03d}','text':c['text'],'source_fact_ids':ids,'status':'supported','reason':reason,'output_ref':f'{c["file"]}:L{c["line"]}','source_evidence':[{'file':'rich_profile.json','fact_id':x,'en':facts[x]['en'],'zh':facts[x]['zh'],**{k:facts[x][k] for k in ['start_date','end_date'] if k in facts[x]}} for x in ids]})
ratings=config['ratings']; weights={'jd_relevance':35,'clarity':25,'supported_achievements':25}
dims=[{'id':k,'weight':w,'status':'assessed','rating':ratings[k],'reason':config['dimension_reasons'][k],'evidence_refs':config['dimension_evidence'][k]} for k,w in weights.items()]
dims.append({'id':'format_readability','weight':15,'status':'not_assessed','rating':None,'reason':'Only Markdown content; no actual DOCX/PDF or rendered/extracted artifact. Original templates missing.'})
rubric=root.parent.parent/'research/evaluation/rubric.json'
result={'schema_version':'1.0','experiment_id':'native-pilot-001','pair':n,'evaluation_source':'llm_judge_unvalidated','judge':{'agent':'/root/evaluate_bilingual_pilot','model_identity':'unknown','independent_from_generator':True,'human_hr_label':False},'scope':'Provisional bilingual content-only presentation assessment conditional on synthetic facts, not person ranking or hire probability.','input_hashes':{f:sha(p/f) for f in ['profile.json','rich_profile.json','job.json']},'output_hashes':{f:sha(p/f) for f in ['resume.en.md','resume.zh.md','claim_ledger.json','external_gap_notes.json','decision_record.json']},'rubric_sha256':sha(rubric),'factual_fidelity':{'state':'pass','claim_count':len(claims),'claims':claims,'method':'Independent semantic reading of every material resume line in both languages against profile facts and rich date fields; generator ledger used as locator, not accepted as proof.','bilingual_notes':config['bilingual_notes']},'requirement_coverage':config['requirement_coverage'],'dimensions':dims,'overall_score':None,'assessed_score':round(100*sum(weights[k]*ratings[k]/4 for k in weights)/85),'assessed_weight':85,'score_notice':'Unvalidated partial diagnostic; not comparable to full scores, different profiles or hiring outcomes. No improvement inference across sequential distinct pairs.','export_ready':False,'feedback':config['feedback'],'feedback_policy':'Apply only to next distinct pair; preserve this sample unchanged. After last pair retain future recommendations without additional generation.','limitations':['Synthetic facts, not independently verified real work.','No human expert calibration or adjudication; model identity not exposed.','No trained model, paid API call, held-out benchmark or measured improvement.','Original template/font/margin dependencies unavailable; skill formatting requirements remain unverified.','No PDF/DOCX extraction, pagination, final-line width, full-page density, font or Word-setting checks.'],'unsupported_claims':[]}
(p/'evaluation.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
print(p/'evaluation.json');print(result['assessed_score'])
